// Browser back button support for all sub-pages
var _closingFromPopstate = false;
window.addEventListener("popstate", function(ev) {
  var subPages = [
    { el: "postDetailPage", close: function(){ closePostDetailPage(); } },
    { el: "behaviorPage", close: function(){ switchTab("profile"); } },
    { el: "dashboardPage", close: function(){ switchTab("profile"); } },
    { el: "contentCenterPage", close: function(){ switchTab("profile"); } },
    { el: "adminBannerPage", close: function(){ switchTab("profile"); } },
    { el: "adminAnnouncementPage", close: function(){ switchTab("profile"); } },
    { el: "adminUserPage", close: function(){ switchTab("profile"); } }
  ];
  for(var i=0;i<subPages.length;i++){
    var el=document.getElementById(subPages[i].el);
    if(el&&!el.classList.contains("hidden")){
      _closingFromPopstate=true;
      subPages[i].close();
      _closingFromPopstate=false;
      return;
    }
  }
});

// Pull-to-refresh for homepage
(function() {
  var startY = 0, pulling = false, refreshing = false;
  var indicator = null;
  var threshold = 70;
  var homePage = null;

  function initPTR() {
    homePage = document.getElementById("homePage");
    if (!homePage) return;
    // Create indicator
    indicator = document.createElement("div");
    indicator.id = "ptrIndicator";
    indicator.style.cssText = "position:fixed;top:0;left:0;right:0;height:0;overflow:hidden;display:flex;align-items:center;justify-content:center;z-index:9999;transition:height 0.25s ease;background:rgba(255,255,255,0.95);font-size:14px;color:#666;";
    indicator.innerHTML = "下拉刷新";
    document.body.appendChild(indicator);

    document.addEventListener("touchstart", function(e) {
      if (currentTab !== "home" || refreshing) return;
      var scrollTop = document.scrollingElement.scrollTop || document.documentElement.scrollTop;
      if (scrollTop <= 0) {
        startY = e.touches[0].clientY;
        pulling = true;
      }
    }, { passive: true });

    document.addEventListener("touchmove", function(e) {
      if (!pulling || currentTab !== "home") return;
      var dy = e.touches[0].clientY - startY;
      if (dy > 0) {
        var h = Math.min(dy * 0.5, 120);
        indicator.style.height = h + "px";
        indicator.innerHTML = h >= threshold ? "松开刷新" : "下拉刷新";
      }
    }, { passive: true });

    document.addEventListener("touchend", function(e) {
      if (!pulling) return;
      pulling = false;
      var h = parseFloat(indicator.style.height) || 0;
      if (h >= threshold) {
        refreshing = true;
        indicator.style.height = "50px";
        indicator.innerHTML = "正在刷新…";
        loadPosts({ reset: true });
        setTimeout(function() {
          indicator.style.height = "0";
          refreshing = false;
          setTimeout(function() { indicator.innerHTML = "下拉刷新"; }, 300);
        }, 800);
      } else {
        indicator.style.height = "0";
      }
    }, { passive: true });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initPTR);
  } else {
    initPTR();
  }
})();
